    </div>
    <div class="players">
      <div class="player">
        <div class="avatar btn" title="Roxy">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.svg" width="54" height="54" alt="Roxy avatar">
        </div>
        <div>
          <div class="player-name">ROXY</div>
          <div class="clock pink" id="whiteClock">6.9s</div>
        </div>
      </div>
      <div class="score">0 0</div>
      <div class="player">
        <div class="avatar bot btn" title="Julien Song">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/024.png" width="48" height="48" alt="Bot avatar">
        </div>
        <div>
          <div class="player-name">Julien Song</div>
          <div class="clock" id="blackClock">1.0s</div>
        </div>
      </div>
    </div>
    <div class="top-right">
      <span class="flag btn" title="France">🇫🇷</span>
      <span class="tiny-knight btn" title="Chess">♘</span>
      <span class="badge btn" title="Rating">133</span>
    </div>
  </header>
  <main class="game">
    <div class="capture-note" id="captureNote"></div>
    <div class="board" id="board" aria-label="Chess board"></div>
    <div class="game-footer" id="gameFooter"></div>
  </main>
</div>
<a class="remove-ads left btn">Remove ads</a>
<a class="remove-ads right btn">Remove ads</a>
<script>
(() => {
  const boardEl = document.getElementById('board');
  const note = document.getElementById('captureNote');
  const footer = document.getElementById('gameFooter');
  const files = ['h','g','f','e','d','c','b','a'];
  const glyph = {
    wk:'♔', wq:'♕', wr:'♖', wb:'♗', wn:'♘', wp:'♙',
    bk:'♚', bq:'♛', br:'♜', bb:'♝', bn:'♞', bp:'♟'
  };
  const board = Array.from({length:8}, () => Array(8).fill(null));
  // White's knight has already developed to the third rank.
  ['wr',null,'wb','wk','wq','wb',null,'wr'].forEach((p,c) => board[0][c]=p);
  ['wp','wp','wp','wp','wp','wp','wp','wp'].forEach((p,c) => board[1][c]=p);
  board[2][2] = 'wn';
  ['bp','bp','bp','bp','bp','bp','bp','bp'].forEach((p,c) => board[6][c]=p);
  ['br','bn','bb','bk','bq','bb','bn','br'].forEach((p,c) => board[7][c]=p);

  let selected = null;
  let previous = [[2,2],[2,2]];
  let legal = [];
  let captures = 0;
  let moveCount = 0;

  function squareClass(r,c) {
    let cls = 'square ' + ((r+c)%2 ? 'dark' : 'light');
    if (previous.some(([pr,pc]) => pr===r && pc===c) && moveCount) cls += ' last';
    if (selected && selected[0]===r && selected[1]===c) cls += ' selected';
    if (legal.some(([lr,lc]) => lr===r && lc===c)) cls += ' legal' + (board[r][c] ? ' occupied' : '');
    return cls;
  }
  function render() {
    boardEl.innerHTML = '';
    for (let r=0; r<8; r++) {
      for (let c=0; c<8; c++) {
        const sq = document.createElement('div');
        sq.className = squareClass(r,c);
        sq.dataset.r = r; sq.dataset.c = c;
        if (c===0) {
          const rank = document.createElement('span');
          rank.className = 'rank';
          rank.textContent = String(r+1);
          sq.appendChild(rank);
        }
        const p = board[r][c];
        if (p) {
          const piece = document.createElement('span');
          piece.className = 'piece ' + (p[0]==='w' ? 'white' : 'black');
          piece.textContent = glyph[p];
          piece.draggable = true;
          piece.addEventListener('dragstart', e => {
            selected = [r,c]; legal = [];
            e.dataTransfer.setData('text/plain', `${r},${c}`);
            setTimeout(render, 0);
          });
          sq.appendChild(piece);
        }
        if (r===7) {
          const file = document.createElement('span');
          file.className = 'file';
          file.textContent = files[c];
          sq.appendChild(file);
        }
        sq.addEventListener('click', () => clickSquare(r,c));
        sq.addEventListener('dragover', e => e.preventDefault());
        sq.addEventListener('drop', e => {
          e.preventDefault();
          const from = (e.dataTransfer.getData('text/plain') || '').split(',').map(Number);
          if (from.length===2 && !Number.isNaN(from[0])) makeMove(from[0],from[1],r,c);
        });
        boardEl.appendChild(sq);
      }
    }
  }
  function clickSquare(r,c) {
    if (selected && selected[0]===r && selected[1]===c) {
      selected = null; legal=[]; render(); return;
    }
    if (selected && board[selected[0]][selected[1]]) {
      if (board[r][c] && board[r][c][0]===board[selected[0]][selected[1]][0]) {
        selected=[r,c]; legal=[]; render(); return;
      }
      makeMove(selected[0],selected[1],r,c);
      return;
    }
    if (board[r][c]) {
      selected=[r,c];
      legal = [[Math.max(0,r-1),c],[Math.min(7,r+1),c],[r,Math.max(0,c-1)],[r,Math.min(7,c+1)]]
        .filter(([rr,cc]) => rr!==r || cc!==c);
      render();
    }
  }
  function makeMove(fr,fc,tr,tc) {
    if (!board[fr][fc] || (fr===tr && fc===tc)) return;
    const taken = board[tr][tc];
    board[tr][tc] = board[fr][fc];
    board[fr][fc] = null;
    previous = [[fr,fc],[tr,tc]];
    moveCount++;
    if (taken) {
      captures++;
      note.innerHTML = `<span class="mini-piece">${glyph[taken]}</span> +${captures}`;
      footer.innerHTML = `<span class="footer-piece">♙</span> +${captures}`;
    } else {
      note.innerHTML = '';
      footer.innerHTML = captures ? `<span class="footer-piece">♙</span> ${captures}` : '';
    }
    selected=null; legal=[];
    render();
  }
  render();
})();
</script>
</body>
